590	    pub async fn lookup_by_name<OC: ObjectClient>(
591	        &self,
592	        client: &OC,
593	        parent_ino: InodeNo,
594	        name: &OsStr,
595	        allow_cache: bool,
596	    ) -> Result<LookedUp, InodeError> {
597	        let name = name
598	            .to_str()
599	            .ok_or_else(|| InodeError::InvalidFileName(name.to_owned()))?;
600	
601	        // This should be impossible, but just to be safe, explicitly reject lookups to files that
602	        // end with '/', since they could be shadowed by directories.
603	        if name.ends_with('/') {
