625	    /// Lookup an [Inode] against known directory entries in the parent,
626	    /// verifying any returned entry has not expired.
627	    fn cache_lookup(&self, parent_ino: InodeNo, name: &str) -> Option<LookedUp> {
628	        fn do_cache_lookup(parent: Inode, name: &str) -> Option<LookedUp> {
629	            match &parent.get_inode_state().ok()?.kind_data {
630	                InodeKindData::File { .. } => unreachable!("parent should be a directory!"),
631	                InodeKindData::Directory { children, .. } => {
632	                    let inode = children.get(name)?;
633	                    let inode_stat = &inode.get_inode_state().ok()?.stat;
634	                    if inode_stat.is_valid() {
635	                        let lookup = LookedUp {
636	                            inode: inode.clone(),
637	                            stat: inode_stat.clone(),
638	                        };
639	                        return Some(lookup);
640	                    }
641	                }
642	            };
643	
644	            None
645	        }
646	
647	        let lookup = self
648	            .get(parent_ino)
649	            .ok()
650	            .and_then(|parent| do_cache_lookup(parent, name));
651	
652	        match &lookup {
653	            Some(lookup) => trace!("lookup returned from cache: {:?}", lookup),
654	            None => trace!("no lookup available from cache"),
655	        }
656	        metrics::counter!("metadata_cache.cache_hit", lookup.is_some().into());
657	
658	        lookup
659	    }
